#[no_mangle]
#[inline(never)]
pub fn original_index(value: f64) -> Option<u32> {
    let js = JSValue::from_bits(value.to_bits());
    if js.is_int32() {
        return (js.as_int32() >= 0).then_some(js.as_int32() as u32);
    }
    (js.is_number()
        && value.is_finite()
        && value >= 0.0
        && value.fract() == 0.0
        && value <= (u32::MAX - 1) as f64)
        .then_some(value as u32)
}
